import React, { useEffect, useState } from 'react';
import PriceTrendChart from './PriceTrendChart';
import SellingTrendChart from './SellingTrendChart';
import ProductDetailsInventory from './ProductDetailsInventory';
import './productDetails.css';
import { useParams } from 'react-router-dom';

function ProductDetails({ getProductByNr, getSuppliersByProductnr }) {

    const { id } = useParams();

    const [product, setProduct] = useState(null);
    const [suppliers, setSuppliers] = useState([]);

    useEffect(() => {
          getProductByNr(id).then(data => setProduct(data));
    }, [getProductByNr]);

    useEffect(() => {
        if (product && product.productnr) {
            getSuppliersByProductnr(product.productnr).then(data => setSuppliers(data));
        }
    }, [product, getSuppliersByProductnr]);

    return (
        <div className="product-details">

            {product != null && 
                <div className='product-header'>
                    <div className='general-info' key={product.productnr}> {/* should show only details about product that choose user */}
                        <h1>{product.name}</h1>
                        <section className='price-info'>
                            <h4>Price:</h4>
                            <h5>{product.sellprice}</h5>
                        </section>
                    </div>

                    <div className='picture' key={product.productnr}>              
                        <section>
                            <img src={product.image}></img>
                        </section>
                    </div>
                </div>
            }

            <div className='product-supplier'>
                <h3>Suppliers</h3>
                <div className="table-container">
                    <table>
                        <thead>
                            <tr>
                                <th>Supplier Name</th>
                                <th>Contact Person</th>
                                <th>Phone</th>
                            </tr>
                        </thead>
                        <tbody>
                            {suppliers && suppliers.map(supplier => (
                                <tr key={supplier.supplier.suppliernr}>
                                    <td>{supplier.supplier.name}</td>
                                    <td>{supplier.supplier.contact}</td>
                                    <td>{supplier.supplier.phone}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>

            <div className='product-location'>

                <h3>Warehouse Inventory</h3>
                <div className="table-container">
                    <ProductDetailsInventory />
                </div>

            </div>

            <div className='charts-holder'>


                <div className='chart-info mb-5'>

                    <h3>Selling Trend</h3>

                    <SellingTrendChart />


                </div>

                <div className='chart-info mb-5'>

                    <h3>Price Trend</h3>

                    <PriceTrendChart />


                </div>

            </div>


        </div>

    )
}

export default ProductDetails;
